import * as React from 'react'
import { Eye, EyeOff } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from './ui/button'

type Strength = 'weak' | 'fair' | 'strong'

const STRENGTH_LABEL: Record<Strength, string> = {
  weak: 'Weak',
  fair: 'Fair',
  strong: 'Strong',
}

const STRENGTH_BAR: Record<Strength, string> = {
  weak: 'w-1/3 bg-destructive',
  fair: 'w-2/3 bg-chart-4',
  strong: 'w-full bg-primary',
}

export function passwordStrength(password: string): Strength {
  const kinds = [/[a-z]/i, /\d/, /[^a-z\d]/i].filter((kind) =>
    kind.test(password)
  ).length
  if (password.length >= 12 && kinds === 3) return 'strong'
  if (password.length >= 8 && kinds >= 2) return 'fair'
  return 'weak'
}

type PasswordInputProps = Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  'type'
> & {
  ref?: React.Ref<HTMLInputElement>
  /** Shows how strong the typed password is, under the input. */
  showStrength?: boolean
}

export function PasswordInput({
  className,
  disabled,
  ref,
  showStrength = false,
  onChange,
  ...props
}: PasswordInputProps) {
  const [showPassword, setShowPassword] = React.useState(false)
  const [typed, setTyped] = React.useState(String(props.defaultValue ?? ''))
  const value = props.value === undefined ? typed : String(props.value)
  const strength = value === '' ? undefined : passwordStrength(value)

  return (
    <div className={cn('rounded-md', className)}>
      <div className='relative'>
        <input
          type={showPassword ? 'text' : 'password'}
          className='flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-xs transition-colors file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:ring-1 focus-visible:ring-ring focus-visible:outline-hidden disabled:cursor-not-allowed disabled:opacity-50'
          ref={ref}
          disabled={disabled}
          onChange={(event) => {
            setTyped(event.target.value)
            onChange?.(event)
          }}
          {...props}
        />
        <Button
          type='button'
          size='icon'
          variant='ghost'
          disabled={disabled}
          className='absolute inset-e-1 top-1/2 h-6 w-6 -translate-y-1/2 rounded-md text-muted-foreground'
          onClick={() => setShowPassword((prev) => !prev)}
        >
          {showPassword ? <Eye size={18} /> : <EyeOff size={18} />}
          <span className='sr-only'>
            {showPassword ? 'Hide password' : 'Show password'}
          </span>
        </Button>
      </div>
      {showStrength && strength !== undefined ? (
        <div className='mt-2 flex items-center gap-2' aria-live='polite'>
          <div className='h-1.5 flex-1 overflow-hidden rounded-full bg-muted'>
            <div
              className={cn(
                'h-full rounded-full transition-all',
                STRENGTH_BAR[strength]
              )}
            />
          </div>
          <span className='text-xs text-muted-foreground'>
            <span className='sr-only'>Password strength: </span>
            {STRENGTH_LABEL[strength]}
          </span>
        </div>
      ) : null}
    </div>
  )
}

import type { Meta, Story } from '@forgebook/react'
import { PasswordInput } from './password-input'

export default {
  title: 'components/PasswordInput',
  component: PasswordInput,
} satisfies Meta<typeof PasswordInput>

export const Default: Story<typeof PasswordInput> = {
  args: { placeholder: 'Password' },
  parameters: { main: true },
}

export const Weak: Story<typeof PasswordInput> = {
  args: { showStrength: true, defaultValue: 'abc' },
}

export const Fair: Story<typeof PasswordInput> = {
  args: { showStrength: true, defaultValue: 'abcd1234' },
}

export const Strong: Story<typeof PasswordInput> = {
  args: { showStrength: true, defaultValue: 'Tr0ub4dor&3xyz!' },
}
